import csv, numpy as np, subprocess, json
rows={int(r['item']):r for r in csv.DictReader(open('data/pool.csv'))}
def load(fs):
    d={}
    for f in fs:
        for r in csv.DictReader(open(f)):
            k=[c for c in r if c not in('item','model')][0]
            d.setdefault(int(r['item']),[]).append(int(r[k]))
    return d
rev={'A':load(['data/review_A_002.csv','data/review_A_006.csv']),'B':load(['data/review_B_003.csv','data/review_B_007.csv'])}
ver={'A':load(['data/verify_A_000.csv']),'B':load(['data/verify_B_001.csv'])}
rng=np.random.default_rng(7)
plan={}
for m in 'AB':
    L=np.array([int(rows[i]['len_'+m]) for i in range(600)]); R=np.array([rev[m][i][0] for i in range(600)])
    qs=np.quantile(L[R==1],[0,.25,.5,.75,1.0]); qs[-1]+=1
    print(m,"review pass rate",R.mean(),"len quartiles of review-passed",qs.round())
    strata={}
    for b in range(4):
        idx=[i for i in range(600) if R[i]==1 and qs[b]<=L[i]<qs[b+1]]
        strata[('r1',b)]=idx
    strata[('r0',0)]=[i for i in range(600) if R[i]==0]
    for k,idx in strata.items():
        done=[i for i in idx if i in ver[m]]
        print(f"  {m} stratum {k}: N={len(idx)} verified={len(done)} truthpass={np.mean([ver[m][i][0] for i in done]) if done else float('nan'):.2f}")
    plan[m]=strata
# allocation of 104 verifies: B r1 buckets: 8,12,18,26 =64 ; B r0: 8 ; A r1 buckets: 4,5,6,9=24 ; A r0: 8  -> total 104
alloc={'B':{('r1',0):8,('r1',1):12,('r1',2):18,('r1',3):26,('r0',0):8},'A':{('r1',0):4,('r1',1):5,('r1',2):6,('r1',3):9,('r0',0):8}}
tot=0
for m in 'AB':
    pick=[]
    for k,n in alloc[m].items():
        cand=[i for i in plan[m][k] if i not in ver[m]]
        pick+=list(rng.choice(cand,size=n,replace=False))
    pick=sorted(int(i) for i in pick); tot+=len(pick)
    open(f'data/verify2_items_{m}.txt','w').write(','.join(map(str,pick)))
    print(m,"picked",len(pick))
print("total verifies",tot,"cost",tot*2)
